long size = Files.size(file);
String type = switch (ext(file.toString())) {
    case "html" -> "text/html; charset=UTF-8";
    case "csv"  -> "text/csv; charset=UTF-8";
    case "png"  -> "image/png";
    default     -> "application/octet-stream";
};
os.write(("HTTP/1.1 200 OK\r\nContent-Type: " + type
    + "\r\nContent-Length: " + size + "\r\n\r\n").getBytes("ISO-8859-1"));

Files.copy(file, os);      // 바이트를 그대로 흘린다
os.flush();

