if (target.contains("..")) {          // 디코딩 전의 원문을 본다
    error(os, 403, "Forbidden", "밖으로 나갈 수 없습니다\n");
    return;
}
Path file = Path.of(base + URLDecoder.decode(target, UTF_8));   // 여기서 디코딩한다

String decoded = URLDecoder.decode(target, UTF_8);
Path file = base.resolve(decoded.substring(1)).normalize();   // .. 를 실제로 접는다
if (!file.startsWith(base)) {                                 // 접은 결과로 검사한다
    error(os, 403, "Forbidden", "밖으로 나갈 수 없습니다\n");
    return;
}
